def _font_dirs():
    env = os.environ.get("MONO_UI_FONTS")
    if env:
        yield Path(env)
    here = Path(__file__).resolve()
    for up in here.parents:
        cand = up / "fonts" / "ttf"
        if cand.is_dir():
            yield cand
            break


def load_fonts() -> list[str]:
    """Register bundled TTFs for any family that isn't installed. Returns the families loaded."""
